#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <math.h>

#define MICROFIREWORKS_PATH_ALLDATA (\
	"public/presentations/microfireworks/data/all-position-velocity.txt"\
)

#define MICROFIREWORKS_PATH_DATA (\
	"public/presentations/microfireworks/data/position-velocity.txt"\
)

#define MICROFIREWORKS_PATH_OUTPUT (\
	"public/presentations/microfireworks/data/output.txt"\
)

#define MICROFIREWORKS_PATH_BKTOUT (\
	"public/presentations/microfireworks/data/bucket-output.txt"\
)

// NOTE this file is not generated by this application, it contains the data in
// MICROFIREWORKS_PATH_BKTOUT after excluding the data points that correspond to
// regions far from the TiO2 particle (meaning that do not follow a linear trend)
// This application applies the linear regression technique to the region near the
// particle as it's common when dealing with limiting cases
#define MICROFIREWORKS_PATH_LINEARIZE (\
	"public/presentations/microfireworks/data/filtered-bucket-output.txt"\
)

#define MICROFIREWORKS_MAX_NUMEL 256
#define MICROFIREWORKS_BUF_SIZE 128

#define MICROFIREWORKS_BUCKET_START 15
#define MICROFIREWORKS_BUCKET_END 155
#define MICROFIREWORKS_BUCKET_STEP 10
#define MICROFIREWORKS_BUCKET_SIZE (\
	(MICROFIREWORKS_BUCKET_END - MICROFIREWORKS_BUCKET_START) / MICROFIREWORKS_BUCKET_STEP\
)

// TODO refactor linear regression code or keep this function as it is and write another
// version that reads the data from a file and reports the regression data including
// the goodness of the fit
void linear_regression(void) {
	double D1 = 0;
	double D2 = 0;
	double Delta = 0;
	double sumX = 0;
	double sumY = 0;
	double sumXX = 0;
	double sumXY = 0;
	double diff = 0;
	double avgX = 0;
	double avgY = 0;
	double stdX = 0;
	double stdY = 0;
	double invStdX = 0;
	double invStdY = 0;
	double slopeRegression = 0;
	double interceptRegression = 0;
	char buf[MICROFIREWORKS_BUF_SIZE];
	double x[MICROFIREWORKS_MAX_NUMEL];
	double y[MICROFIREWORKS_MAX_NUMEL];
	double mu[MICROFIREWORKS_MAX_NUMEL];
	double nu[MICROFIREWORKS_MAX_NUMEL];
	double positions[MICROFIREWORKS_MAX_NUMEL];
	double velocities[MICROFIREWORKS_MAX_NUMEL];
	char *ptr_line = NULL;
	size_t size_line = 0;
	errno = 0;
	FILE *fout = fopen(MICROFIREWORKS_PATH_OUTPUT, "w");
	if (!fout) {
		if (errno) {
			fprintf(stderr, "error: %s\n", strerror(errno));
		}
		exit(EXIT_FAILURE);
	}

	FILE *file = fopen(MICROFIREWORKS_PATH_DATA, "r");
	if (!file) {
		if (errno) {
			fprintf(stderr, "error: %s\n", strerror(errno));
		}
		exit(EXIT_FAILURE);
	}

	double xmax = 0;
	double ymax = 0;
	double width = 0;
	double height = 0;
	int idxLine = 0;
	int numRows = 0;
	ssize_t bytes_read = 0;
	do {
		char tab = 0;
		char space = 0;
		char newLine = 0;
		double position = 0;
		double velocity = 0;
		char xmaxProp[] = "xmax:";
		char ymaxProp[] = "ymax:";
		char widthProp[] = "width:";
		char heightProp[] = "height:";

		fprintf(stdout, "rows: %d\n", numRows);
		if (MICROFIREWORKS_MAX_NUMEL <= numRows) {
			fprintf(stderr, "%s\n", "datafile exceeds expected number of rows");
			free(ptr_line);
			ptr_line = NULL;
			size_line = 0;
			fclose(file);
			exit(EXIT_FAILURE);
		}

		bytes_read = getline(&ptr_line, &size_line, file);

		if (MICROFIREWORKS_BUF_SIZE <= size_line) {
			fprintf(stderr, "%s\n", "line exceeds expected number of bytes");
			free(ptr_line);
			ptr_line = NULL;
			size_line = 0;
			fclose(file);
			exit(EXIT_FAILURE);
		}

		fprintf(stdout, "%s", ptr_line);
		char *headDelim = strstr(ptr_line, ":");
		if (!headDelim && (1 < bytes_read)) {
			memset(buf, 0, sizeof(buf));
			memcpy(buf, ptr_line, sizeof(buf));
			buf[sizeof(buf) - 1] = 0;
			int rc = sscanf(buf, "%lf%c%lf%c", &position, &tab, &velocity, &newLine);
			if (4 != rc) {
				fprintf(stderr, "data scan failed at line %d\n", idxLine);
			}
			else {
				fprintf(stdout, "position: %lf velocity: %lf\n", position, velocity);
			}

			positions[numRows] = position;
			velocities[numRows] = velocity;

			++numRows;
		}
		else {
			char *prop = strstr(ptr_line, widthProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(widthProp) - 1), "%c%lf%c", &space, &width, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "width: %lf\n", width);
			}

			prop = strstr(ptr_line, heightProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(heightProp) - 1), "%c%lf%c", &space, &height, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "height: %lf\n", height);
			}

			prop = strstr(ptr_line, xmaxProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(xmaxProp) - 1), "%c%lf%c", &space, &xmax, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "xmax: %lf\n", xmax);
			}

			prop = strstr(ptr_line, ymaxProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(ymaxProp) - 1), "%c%lf%c", &space, &ymax, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "ymax: %lf\n", ymax);
			}
		}
		++idxLine;
	} while (-1 != bytes_read);

	if (!xmax || !ymax || !width || !height) {
		fprintf(stderr, "%s\n", "property scan failure");
		free(ptr_line);
		ptr_line = NULL;
		size_line = 0;
		fclose(file);
		exit(EXIT_FAILURE);
	}

	double const widthInv = 1.0 / width;
	double const heightInv = 1.0 / height;
	double const xscale = xmax * widthInv;
	double const yscale = ymax * heightInv;
	for (int i = 0; i != numRows; ++i) {
		positions[i] *= xscale;
	}

	for (int i = 0; i != numRows; ++i) {
		velocities[i] *= yscale;
	}

	for (int i = 0; i != numRows; ++i) {
		x[i] = (1.0 / positions[i]);
	}

	memcpy(y, velocities, sizeof(velocities));

	sumX = 0;
	sumY = 0;
	sumXY = 0;
	sumXX = 0;
	// least squares regression
	for (int i = 0; i != numRows; ++i) {
		sumX += x[i];
		sumY += y[i];
		sumXX += (x[i] * x[i]);
		sumXY += (x[i] * y[i]);
	}

	Delta = (sumXX * numRows) - (sumX * sumX);
	D1 = (sumXY * numRows) - (sumX * sumY);
	D2 = (sumXX * sumY) - (sumX * sumXY);
	slopeRegression = D1 / Delta;
	interceptRegression = D2 / Delta;

	fprintf(stdout, "slope: %lf\n", slopeRegression);
	fprintf(stdout, "intercept: %lf\n", interceptRegression);

	// R-squared computation
	avgX = sumX / numRows;
	avgY = sumY / numRows;

	diff = 0;
	for (int i = 0; i != numRows; ++i) {
		diff += (x[i] - avgX) * (x[i] - avgX);
	}

	diff /= (numRows - 1);
	stdX = sqrt(diff);
	invStdX = 1.0 / stdX;

	diff = 0;
	for (int i = 0; i != numRows; ++i) {
		diff += (y[i] - avgY) * (y[i] - avgY);
	}

	diff /= (numRows - 1);
	stdY = sqrt(diff);
	invStdY = 1.0 / stdY;

	for (int i = 0; i != numRows; ++i) {
		mu[i] = (x[i] - avgX) * invStdX;
	}

	for (int i = 0; i != numRows; ++i) {
		nu[i] = (y[i] - avgY) * invStdY;
	}

	sumX = 0;
	sumY = 0;
	sumXY = 0;
	sumXX = 0;
	for (int i = 0; i != numRows; ++i) {
		sumX += mu[i];
		sumY += nu[i];
		sumXX += (mu[i] * mu[i]);
		sumXY += (mu[i] * nu[i]);
	}

	Delta = (sumXX * numRows) - (sumX * sumX);
	D1 = (sumXY * numRows) - (sumX * sumY);
	slopeRegression = D1 / Delta;

	fprintf(stdout, "r-squared: %lf\n", slopeRegression * slopeRegression);

	for (int i = 0; i != numRows; ++i) {
		fprintf(fout, "%lf\t%lf\n", x[i], y[i]);
	}

	free(ptr_line);
	ptr_line = NULL;
	size_line = 0;
	fclose(file);
	fclose(fout);
	return;
}

// we process the position velocity data for plotting position against some average velocity with error bars. To achieve this we put the data into buckets of uniform size to perform the averaging so that we may have around five data points for each position. The logic to do this is fairly easy because you can easily map the position data to a bucket and also count how many points are in the bucket. The latter is useful to compute the average velocity and standard deviation.
void aggregate(void) {
	char buf[MICROFIREWORKS_BUF_SIZE];
	int bucket_count[MICROFIREWORKS_BUCKET_SIZE];
	double bucket_position[MICROFIREWORKS_BUCKET_SIZE];
	double bucket_velocity[MICROFIREWORKS_BUCKET_SIZE];
	double bucket_error[MICROFIREWORKS_BUCKET_SIZE];
	double positions[MICROFIREWORKS_MAX_NUMEL];
	double velocities[MICROFIREWORKS_MAX_NUMEL];
	char *ptr_line = NULL;
	size_t size_line = 0;
	double posmin = 0;
	double posmax = 0;
	errno = 0;
	FILE *fout = fopen(MICROFIREWORKS_PATH_BKTOUT, "w");
	if (!fout) {
		if (errno) {
			fprintf(stderr, "error: %s\n", strerror(errno));
		}
		exit(EXIT_FAILURE);
	}

	FILE *file = fopen(MICROFIREWORKS_PATH_ALLDATA, "r");
	if (!file) {
		if (errno) {
			fprintf(stderr, "error: %s\n", strerror(errno));
		}
		exit(EXIT_FAILURE);
	}

	double xmax = 0;
	double ymax = 0;
	double width = 0;
	double height = 0;
	int idxLine = 0;
	int numRows = 0;
	ssize_t bytes_read = 0;
	do {
		char tab = 0;
		char space = 0;
		char newLine = 0;
		double position = 0;
		double velocity = 0;
		char xmaxProp[] = "xmax:";
		char ymaxProp[] = "ymax:";
		char widthProp[] = "width:";
		char heightProp[] = "height:";

		fprintf(stdout, "rows: %d\n", numRows);
		if (MICROFIREWORKS_MAX_NUMEL <= numRows) {
			fprintf(stderr, "%s\n", "datafile exceeds expected number of rows");
			free(ptr_line);
			ptr_line = NULL;
			size_line = 0;
			fclose(file);
			exit(EXIT_FAILURE);
		}

		bytes_read = getline(&ptr_line, &size_line, file);

		if (MICROFIREWORKS_BUF_SIZE <= size_line) {
			fprintf(stderr, "%s\n", "line exceeds expected number of bytes");
			free(ptr_line);
			ptr_line = NULL;
			size_line = 0;
			fclose(file);
			exit(EXIT_FAILURE);
		}

		fprintf(stdout, "%s", ptr_line);
		char *headDelim = strstr(ptr_line, ":");
		if (!headDelim && (1 < bytes_read)) {
			memset(buf, 0, sizeof(buf));
			memcpy(buf, ptr_line, sizeof(buf));
			buf[sizeof(buf) - 1] = 0;
			int rc = sscanf(buf, "%lf%c%lf%c", &position, &tab, &velocity, &newLine);
			if (4 != rc) {
				fprintf(stderr, "data scan failed at line %d\n", idxLine);
			}
			else {
				fprintf(stdout, "position: %lf velocity: %lf\n", position, velocity);
			}

			positions[numRows] = position;
			velocities[numRows] = velocity;

			++numRows;
		}
		else {
			char *prop = strstr(ptr_line, widthProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(widthProp) - 1), "%c%lf%c", &space, &width, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "width: %lf\n", width);
			}

			prop = strstr(ptr_line, heightProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(heightProp) - 1), "%c%lf%c", &space, &height, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "height: %lf\n", height);
			}

			prop = strstr(ptr_line, xmaxProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(xmaxProp) - 1), "%c%lf%c", &space, &xmax, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "xmax: %lf\n", xmax);
			}

			prop = strstr(ptr_line, ymaxProp);
			if (prop) {
				int rc = sscanf(prop + (sizeof(ymaxProp) - 1), "%c%lf%c", &space, &ymax, &newLine);
				if (3 != rc) {
					fprintf(stderr, "property scan failed at line %d\n", idxLine);
				}
				fprintf(stdout, "ymax: %lf\n", ymax);
			}
		}
		++idxLine;
	} while (-1 != bytes_read);

	if (!xmax || !ymax || !width || !height) {
		fprintf(stderr, "%s\n", "property scan failure");
		free(ptr_line);
		ptr_line = NULL;
		size_line = 0;
		fclose(file);
		exit(EXIT_FAILURE);
	}

	double const widthInv = 1.0 / width;
	double const heightInv = 1.0 / height;
	double const xscale = xmax * widthInv;
	double const yscale = ymax * heightInv;

	posmax = -1;
	for (int i = 0; i != numRows; ++i) {
		if (positions[i] > posmax) {
			posmax = positions[i];
		}
	}

	posmin = (1 << 16);
	for (int i = 0; i != numRows; ++i) {
		if (positions[i] < posmin) {
			posmin = positions[i];
		}
	}

	fprintf(stdout, "min: %lf max: %lf\n", posmin, posmax);

	memset(bucket_position, 0, sizeof(bucket_position));
	memset(bucket_velocity, 0, sizeof(bucket_velocity));
	memset(bucket_error, 0, sizeof(bucket_error));
	memset(bucket_count, 0, sizeof(bucket_count));
	for (int i = 0; i != numRows; ++i) {
		int bucket_value = positions[i];
		int bucket_id = (
			(bucket_value - MICROFIREWORKS_BUCKET_START) / MICROFIREWORKS_BUCKET_STEP
		);

		if ((bucket_id >= 0) && (bucket_id < MICROFIREWORKS_BUCKET_SIZE)) {
			bucket_count[bucket_id] += 1;
			bucket_position[bucket_id] += positions[i];
			bucket_velocity[bucket_id] += velocities[i];
		}
	}

	// computes the average velocity for each bucket
	for (int i = 0; i != MICROFIREWORKS_BUCKET_SIZE; ++i) {
		if (bucket_count[i]) {
			bucket_position[i] /= bucket_count[i];
			bucket_velocity[i] /= bucket_count[i];
		}
	}

	for (int i = 0; i != numRows; ++i) {

		int bucket_value = positions[i];
		int bucket_id = (
			(bucket_value - MICROFIREWORKS_BUCKET_START) / MICROFIREWORKS_BUCKET_STEP
		);

		if (bucket_id < MICROFIREWORKS_BUCKET_SIZE) {
			double diff = (velocities[i] - bucket_velocity[bucket_id]);
			double diff2 = diff * diff;
			bucket_error[bucket_id] += diff2;
		}
	}

	for (int i = 0; i != MICROFIREWORKS_BUCKET_SIZE; ++i) {
		if (bucket_count[i]) {
			bucket_error[i] /= bucket_count[i];
			bucket_error[i] = sqrt(bucket_error[i]);
		}
	}

	for (int i = 0; i != MICROFIREWORKS_BUCKET_SIZE; ++i) {
		bucket_position[i] *= xscale;
		bucket_velocity[i] *= yscale;
		bucket_error[i] *= yscale;
	}

	for (int i = 0; i != MICROFIREWORKS_BUCKET_SIZE; ++i) {
		if (bucket_count[i]) {
			fprintf(stdout, "bucket-position: %.2lf bucket-velocity: %.2lf bucket-error: %lf bucket-count: %d\n", bucket_position[i], bucket_velocity[i], bucket_error[i], bucket_count[i]);
		}
	}

	for (int i = 0; i != MICROFIREWORKS_BUCKET_SIZE; ++i) {
		fprintf(
			fout,
			"%lf\t%lf\t%lf\n",
			(1.0 / bucket_position[i]),
			bucket_velocity[i],
			bucket_error[i]
		);
	}

	free(ptr_line);
	ptr_line = NULL;
	size_line = 0;
	fclose(file);
	fclose(fout);
	return;
}

struct data {
	double *x;
	double *y;
	int len;
};

#define __NEOF__ (-1 != rc)

void load(struct data *points) {
	errno = 0;
	FILE *file = fopen(MICROFIREWORKS_PATH_LINEARIZE, "r");
	if (!file) {
		if (errno) {
			fprintf(stderr, "load: %s\n", strerror(errno));
		}
		exit(EXIT_FAILURE);
	}

	int linenum = 0;
	ssize_t rc = 0;
	ssize_t len = 0;
	char *lineptr = NULL;
	size_t linesz = 0;
	size_t bytes = 0;
	do {
		errno = 0;
		rc = len = getline(&lineptr, &linesz, file);
		if (errno) {
			fprintf(stderr, "load: %s\n", strerror(errno));
			fclose(file);
			free(lineptr);
			exit(EXIT_FAILURE);
		}

		if (__NEOF__) {
			fprintf(stdout, "%s", lineptr);
			++linenum;
		}

	} while (__NEOF__);

	if (!linenum) {
		fprintf(stderr, "load: %s\n", "empty file error");
		fclose(file);
		free(lineptr);
		exit(EXIT_FAILURE);
	}

	rewind(file);

	bytes = linenum * sizeof(double);
	points->len = linenum;
	points->x = (double*) malloc(bytes);
	if (!points->x) {
		fprintf(stderr, "load: %s\n", "memory error");
		fclose(file);
		free(lineptr);
		exit(EXIT_FAILURE);
	}
	points->y = (double*) malloc(bytes);
	if (!points->y) {
		fprintf(stderr, "load: %s\n", "memory error");
		fclose(file);
		free(lineptr);
		free(points->x);
		exit(EXIT_FAILURE);
	}

	fprintf(stdout, "%s", "\n\n");
	double *x = points->x;
	double *y = points->y;
	for (int i = 0; i != linenum; ++i, ++x, ++y) {
		double tmp;
		errno = 0;
		getline(&lineptr, &linesz, file);
		if (errno) {
			fprintf(stderr, "load: %s\n", strerror(errno));
			fclose(file);
			free(lineptr);
			free(points->x);
			free(points->y);
			points->len = 0;
			exit(EXIT_FAILURE);
		}
		int numel = sscanf(lineptr, "%lf%lf%lf", x, y, &tmp);
		if (3 != numel) {
			fprintf(stderr, "load: %s\n", "expected assignments failed");
			fclose(file);
			free(lineptr);
			free(points->x);
			free(points->y);
			points->len = 0;
			exit(EXIT_FAILURE);
		}
		fprintf(stdout, "%s", lineptr);
		fprintf(stdout, "%lf\t%lf\t%lf\n", *x, *y, tmp);
	}

	linesz = 0;
	free(lineptr);
	fclose(file);
	return;
}

int main(void) {
	aggregate();
	struct data points = {};
	points.x = NULL;
	points.y = NULL;
	points.len = 0;

	load(&points);

	if (points.len) {
		free(points.x);
		free(points.y);
		points.len = 0;
	}
//	linear_regression();
	return 0;
}

// TODO:
// [x] read the scaling data at the head of the data file
// [x] define an array of suitable size to store the position velocity data, just count the number of rows in the tabulated section to determine this at runtime
// [x] perform the scaling from pixels to the position and velocity units
// [x] check the limiting cases of pure diffusion c(r) = 1/r and
//     reaction-diffusion exp(-r)/r; don't forget that you have to determine ln(c_\inf).
